MARKS = {
    'baja/manchester/menu/design-scope-from-workbench.js': 'applyIndels',
    'py/ssaso/design.py': 'cover_spans',
    'flexigraph/oligo.js': 'WHICH STRAND A COMPOUND SPELLS OUT',
    'baja/manchester/menu/track-design-menu.js': 'cover_spans',
}
root = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/baja-apps')
plan = []
for rel, hunks in OPS.items():
    p = os.path.join(root, rel)
    if not os.path.isfile(p):
        sys.exit('Not found: ' + p + '. Nothing was changed.')
    s = open(p, encoding='utf-8').read()
    crlf = '\r\n' in s
    s = s.replace('\r\n', '\n')
    if MARKS[rel] in s:
        print('Already installed:', p); continue
    for old, new in hunks:
        if s.count(old) != 1:
            sys.exit(p + ' differs from the version this update was made against'
                     + ' (install-allele-selective-tiling.py first?). Nothing was changed.')
        s = s.replace(old, new, 1)
    plan.append((p, s, crlf))
for p, s, crlf in plan:
    shutil.copyfile(p, p + '.before-allele-indels')
    open(p, 'w', encoding='utf-8', newline='').write(s.replace('\n', '\r\n') if crlf else s)
    print('Updated', p)
print('Restart baja-server (it caches scripts), then hard-refresh the editor (Ctrl+Shift+R).')
